from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LiquidityScreenedEqualWeighting(Strategy):
    rationale = (
        "Higher liquidity stocks are more likely to be mispriced or experience less friction "
        "when trading occurs. By equally weighting these stocks, we aim to capture the potential "
        "arbitrage opportunities arising from such conditions."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.is_empty():
            return Signal(information_available_at=stamp, weights={})

        liquidity_scores = (
            history.select(pl.col("symbol"))
            .group_by("symbol")
            .agg((pl.col("volume").sum() / 20).alias("avg_volume"))
            .sort("avg_volume", descending=True)
            .head(self._window)["symbol"]
        ).to_list()

        return Signal(
            information_available_at=stamp,
            weights={s: 1.0 / len(liquidity_scores) for s in liquidity_scores},
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
